import sys

def infix_to_prefix(expression):
    prec = {'+': 1, '-': 1, '*': 2, '/': 2, '^': 3}
    ops = set(prec.keys())

    tokens = []
    i = 0
    n = len(expression)
    while i < n:
        c = expression[i]
        if c in '()':
            tokens.append(c)
            i += 1
        elif c in ops:
            tokens.append(c)
            i += 1
        elif c.isalnum():
            j = i
            while i < n and expression[i].isalnum():
                i += 1
            tokens.append(expression[j:i])
        else:
            i += 1

    reversed_expr = tokens[::-1]
    modified = []
    for token in reversed_expr:
        if token == '(':
            modified.append(')')
        elif token == ')':
            modified.append('(')
        else:
            modified.append(token)

    operands = []
    operators = []

    for token in modified:
        if token.isalnum():
            operands.append(token)
        elif token == '(':
            operators.append(token)
        elif token == ')':
            while operators and operators[-1] != '(':
                op = operators.pop()
                b = operands.pop()
                a = operands.pop()
                operands.append(op + a + b)
            if operators and operators[-1] == '(':
                operators.pop()
        else:
            while (operators and operators[-1] != '(' and
                   prec.get(operators[-1], 0) > prec.get(token, 0)):
                op = operators.pop()
                b = operands.pop()
                a = operands.pop()
                operands.append(op + a + b)
            operators.append(token)

    while operators:
        op = operators.pop()
        b = operands.pop()
        a = operands.pop()
        operands.append(op + a + b)

    return operands[0] if operands else ''

def main():
    expression = sys.stdin.readline().strip()
    if not expression:
        print('')
    else:
        print(infix_to_prefix(expression))

if __name__ == "__main__":
    main()
